class Solution {
  public int maxEqualAdjacentPairs(int[] nums) {
    int base = 0;
    java.util.HashMap<Long, Integer> gain = new java.util.HashMap<>();
    for (int i = 0; i + 1 < nums.length; i++) {
      if (nums[i] == nums[i + 1]) base++;
      else {
        long key =
            (long) Math.min(nums[i], nums[i + 1]) * 2_000_000_000L + Math.max(nums[i], nums[i + 1]);
        gain.merge(key, 1, Integer::sum);
      }
    }
    int best = 0;
    for (int g : gain.values()) best = Math.max(best, g);
    return base + best;
  }
}
